export const save = createEffect(
  (actions$ = inject(Actions), api = inject(ItemsApi)) => actions$.pipe(
    ofType(ItemActions.save),
    concatMap(({ item }) => api.save(item).pipe(
      map(() => ItemApiActions.saveSuccess()),
      catchError(e => of(ItemApiActions.saveFailure({ error: e.message }))),
    )),
  ),
  { functional: true },
);

